sf_entry_uuid = "a4f8c2d1-3b7e-4509-8e6a-f29c14d07531"

# ── Subflow contents ──────────────────────────────────────────────────────────
sf_start = {
  "id": "fetchAndFormatStart",
  "type": "core.trigger.manual",
  "typeVersion": "1.0",
  "display": {"label": "Start"},
  "inputs": {"entryPointId": sf_entry_uuid, "isDefaultEntryPoint": True},
  "outputs": {
    "output": {
      "type": "object",
      "description": "Data passed when manually triggering the workflow.",
      "source": "null",
      "var": "output"
    }
  }
}

sf_get_weather = {
  "id": "getWeather",
  "type": "core.action.http",
  "typeVersion": "1.2",
  "display": {"label": "Get Bellevue Weather"},
  "inputs": {
    "mode": "manual", "method": "GET",
    "url": "https://api.open-meteo.com/v1/forecast?latitude=47.6101&longitude=-122.2015&current=temperature_2m&temperature_unit=fahrenheit",
    "headers": {}, "queryParams": {},
    "body": {"type": "literal", "expression": "", "fieldType": "object"},
    "contentType": "application/json", "timeout": "PT15M",
    "retryCount": 0, "branches": []
  },
  "outputs": {
    "output": {"type": "object", "description": "The return value of the HTTP request",
               "source": {"type": "literal", "expression": "=result.response", "fieldType": "string"}, "var": "output"},
    "error":  {"type": "object", "description": "Error information if the HTTP request fails",
               "source": {"type": "literal", "expression": "=result.Error",    "fieldType": "string"}, "var": "error"}
  },
  "model": {"type": "bpmn:ServiceTask"}
}

sf_format_summary = {
  "id": "formatSummary",
  "type": "core.action.script",
  "typeVersion": "1.0",
  "display": {"label": "Format Weather Summary"},
  "inputs": {
    "script": "const tempF = $vars.getWeather.output.body.current.temperature_2m;\nconst time = $vars.getWeather.output.body.current.time;\nreturn {\n  temperatureF: tempF,\n  summary: 'Bellevue weather today: ' + tempF + 'F at ' + time\n};"
  },
  "outputs": {
    "output": {"type": "object", "description": "The return value of the script",
               "source": {"type": "literal", "expression": "=result.response", "fieldType": "string"}, "var": "output"},
    "error":  {"type": "object", "description": "Error information if the script fails",
               "source": {"type": "literal", "expression": "=result.Error",    "fieldType": "string"}, "var": "error"}
  },
  "model": {"type": "bpmn:ScriptTask"}
}

sf_end = {
  "id": "fetchAndFormatEnd",
  "type": "core.control.end",
  "typeVersion": "1.0",
  "display": {"label": "End"},
  "inputs": {},
  "outputs": {
    "temperatureF": {
      "source": {"type": "jsExpression", "expression": "$vars.formatSummary.output.temperatureF", "fieldType": "number"}
    },
    "summary": {
      "source": {"type": "jsExpression", "expression": "$vars.formatSummary.output.summary", "fieldType": "string"}
    }
  }
}

subflow_def_entry = {
  "subflows": {
    "fetchAndFormat": {
      "nodes": [sf_start, sf_get_weather, sf_format_summary, sf_end],
      "edges": [
        {"id": "sfe_fetchAndFormatStart_output_getWeather_input",
         "sourceNodeId": "fetchAndFormatStart", "sourcePort": "output",
         "targetNodeId": "getWeather",           "targetPort": "input"},
        {"id": "sfe_getWeather_default_formatSummary_input",
         "sourceNodeId": "getWeather",    "sourcePort": "default",
         "targetNodeId": "formatSummary", "targetPort": "input"},
        {"id": "sfe_formatSummary_success_fetchAndFormatEnd_input",
         "sourceNodeId": "formatSummary",     "sourcePort": "success",
         "targetNodeId": "fetchAndFormatEnd", "targetPort": "input"}
      ],
      "variables": {
        "globals": [
          {"id": "temperatureF", "direction": "out", "type": "number", "defaultValue": 0},
          {"id": "summary",      "direction": "out", "type": "string", "defaultValue": ""}
        ],
        "nodes": [
          {"id": "getWeather.output",    "type": "object", "description": "HTTP response from open-meteo API",
           "binding": {"nodeId": "getWeather",    "outputId": "output"}},
          {"id": "getWeather.error",     "type": "object", "description": "Error if weather fetch fails",
           "binding": {"nodeId": "getWeather",    "outputId": "error"}},
          {"id": "formatSummary.output", "type": "object", "description": "Formatted weather summary",
           "binding": {"nodeId": "formatSummary", "outputId": "output"}},
          {"id": "formatSummary.error",  "type": "object", "description": "Error if formatting script fails",
           "binding": {"nodeId": "formatSummary", "outputId": "error"}}
        ]
      },
      "layout": {
        "nodes": {
          "fetchAndFormatStart": {"position": {"x": 200, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
          "getWeather":           {"position": {"x": 450, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
          "formatSummary":        {"position": {"x": 700, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
          "fetchAndFormatEnd":    {"position": {"x": 950, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False}
        }
      }
    }
  }
}

# ── Mutate checkTemperature expression ───────────────────────────────────────
nodes_by_id = {n["id"]: n for n in flow["nodes"]}
nodes_by_id["checkTemperature"]["inputs"]["expression"] = (
    "$vars.fetchAndFormat.output.temperatureF > 60"
)

# ── Mutate end-node output expressions ───────────────────────────────────────
for eid in ("endNiceDay", "endBringJacket"):
    for _, vobj in nodes_by_id[eid]["outputs"].items():
        src = vobj.get("source", {})
        if isinstance(src, dict) and "expression" in src:
            src["expression"] = src["expression"].replace(
                "$vars.formatSummary.output.", "$vars.fetchAndFormat.output."
            )

# ── Build fetchAndFormat node ─────────────────────────────────────────────────
fetchAndFormat_node = {
  "id": "fetchAndFormat",
  "type": "core.subflow",
  "typeVersion": "1.0",
  "display": {"label": "Fetch and Format", "icon": "layers"},
  "inputs": {},
  "outputs": {
    "error": {
      "type": "object", "description": "Error information if the subflow fails",
      "source": "=Error", "var": "error"
    }
  }
}

# ── Replace main-flow nodes & edges ──────────────────────────────────────────
flow["nodes"] = [
    nodes_by_id["start"],
    fetchAndFormat_node,
    nodes_by_id["checkTemperature"],
    nodes_by_id["endNiceDay"],
    nodes_by_id["endBringJacket"],
]

flow["edges"] = [
  {"id": "edge_start_output_fetchAndFormat_input",
   "sourceNodeId": "start",          "sourcePort": "output",
   "targetNodeId": "fetchAndFormat",  "targetPort": "input"},
  {"id": "edge_fetchAndFormat_output_checkTemperature_input",
   "sourceNodeId": "fetchAndFormat",  "sourcePort": "output",
   "targetNodeId": "checkTemperature","targetPort": "input"},
  {"id": "edge_checkTemperature_true_endNiceDay_input",
   "sourceNodeId": "checkTemperature","sourcePort": "true",
   "targetNodeId": "endNiceDay",      "targetPort": "input"},
  {"id": "edge_checkTemperature_false_endBringJacket_input",
   "sourceNodeId": "checkTemperature","sourcePort": "false",
   "targetNodeId": "endBringJacket",  "targetPort": "input"},
]

# ── Add core.subflow definition (keep all existing) ──────────────────────────
flow["definitions"].append(subflow_def)

# ── Subflows section ──────────────────────────────────────────────────────────
flow["subflows"] = subflow_def_entry["subflows"]

# ── Main-flow variables ───────────────────────────────────────────────────────
flow["variables"] = {
  "globals": [
    {"id": "summary", "direction": "out", "type": "object",
     "description": "Weather summary with temperature and message"}
  ],
  "nodes": [
    {"id": "fetchAndFormat.output", "type": "object",
     "description": "Output from fetchAndFormat subflow",
     "binding": {"nodeId": "fetchAndFormat", "outputId": "output"}}
  ]
}

# ── Main-flow layout ──────────────────────────────────────────────────────────
flow["layout"] = {
  "nodes": {
    "start":           {"position": {"x": 200,  "y": 220}, "size": {"width": 96,  "height": 96},  "collapsed": False},
    "fetchAndFormat":  {"position": {"x": 420,  "y": 60},  "size": {"width": 560, "height": 320}, "collapsed": False},
    "checkTemperature":{"position": {"x": 1100, "y": 220}, "size": {"width": 96,  "height": 96},  "collapsed": False},
    "endNiceDay":      {"position": {"x": 1350, "y": 120}, "size": {"width": 96,  "height": 96},  "collapsed": False},
    "endBringJacket":  {"position": {"x": 1350, "y": 320}, "size": {"width": 96,  "height": 96},  "collapsed": False},
  }
}

with open(FLOW, "w") as f:
    json.dump(flow, f, indent=2)

print("Wrote", FLOW)
